insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152001','00000043-0000-4000-8000-000000015200','A','$-\frac16$',1),('00000053-0000-4000-8000-000000152002','00000043-0000-4000-8000-000000015200','B','$0$',2),('00000053-0000-4000-8000-000000152003','00000043-0000-4000-8000-000000015200','C','$\frac16$',3),('00000053-0000-4000-8000-000000152004','00000043-0000-4000-8000-000000015200','D','O limite não existe.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
