insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152001','00000043-0000-4000-8000-000000015200','A substituição inicial deve produzir uma forma indeterminada válida.',1),('00000063-0000-4000-8000-000000152002','00000043-0000-4000-8000-000000015200','Depois de cada derivação, confira se a forma ainda é $0/0$.',2),('00000063-0000-4000-8000-000000152003','00000043-0000-4000-8000-000000015200','Na terceira derivação, a avaliação deixa de ser indeterminada.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015200','$-\frac16$','avaliar uma indeterminação por L’Hôpital repetida. Em $x=0$, numerador e denominador são zero. A razão passa a $(\cos x-1)/(3x^2)$, ainda $0/0$. A segunda razão é $-\sin x/(6x)$, novamente $0/0$. Obtemos $-\cos x/6$, que pode ser avaliada em zero. Como $\cos0=1$, o limite vale $-1/6$. O resultado é $-\frac16$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152001','00000043-0000-4000-8000-000000015200','Teste a forma','Em $x=0$, numerador e denominador são zero.',1),('00000073-0000-4000-8000-000000152002','00000043-0000-4000-8000-000000015200','Aplique a regra uma vez','A razão passa a $(\cos x-1)/(3x^2)$, ainda $0/0$.',2),('00000073-0000-4000-8000-000000152003','00000043-0000-4000-8000-000000015200','Aplique duas vezes','A segunda razão é $-\sin x/(6x)$, novamente $0/0$.',3),('00000073-0000-4000-8000-000000152004','00000043-0000-4000-8000-000000015200','Aplique pela terceira vez','Obtemos $-\cos x/6$, que pode ser avaliada em zero.',4),('00000073-0000-4000-8000-000000152005','00000043-0000-4000-8000-000000015200','Conclua','Como $\cos0=1$, o limite vale $-1/6$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015201','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Determine $a$ e $b$ para que $f(x)=\begin{cases}ax+b,&x<1\\x^2+1,&x\ge1\end{cases}$ seja contínua e tenha derivada em $x=1$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152011','00000043-0000-4000-8000-000000015201','A','$a=2$ e $b=0$',1),('00000053-0000-4000-8000-000000152012','00000043-0000-4000-8000-000000015201','B','$a=1$ e $b=1$',2),('00000053-0000-4000-8000-000000152013','00000043-0000-4000-8000-000000015201','C','$a=2$ e $b=1$',3),('00000053-0000-4000-8000-000000152014','00000043-0000-4000-8000-000000015201','D','$a=0$ e $b=2$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
