insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015201','30000000-0000-4000-8000-000000000019',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152011','00000043-0000-4000-8000-000000015201','Derivabilidade exige continuidade, mas a recíproca não basta.',1),('00000063-0000-4000-8000-000000152012','00000043-0000-4000-8000-000000015201','Iguale primeiro os valores laterais em $x=1$.',2),('00000063-0000-4000-8000-000000152013','00000043-0000-4000-8000-000000015201','Depois iguale as inclinações dos dois ramos no ponto.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015201','$a=2$ e $b=0$','combinar continuidade e derivabilidade em função por partes. O ramo direito vale $1^2+1=2$, então $a+b=2$. À esquerda, $f^{\prime}=a$; à direita, $f^{\prime}=2x$. Em $x=1$, as derivadas laterais exigem $a=2$. Substituir em $a+b=2$ fornece $b=0$. Os dois valores são 2 e as duas inclinações são 2. O resultado é $a=2$ e $b=0$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152011','00000043-0000-4000-8000-000000015201','Imponha continuidade','O ramo direito vale $1^2+1=2$, então $a+b=2$.',1),('00000073-0000-4000-8000-000000152012','00000043-0000-4000-8000-000000015201','Derive os ramos','À esquerda, $f^{\prime}=a$; à direita, $f^{\prime}=2x$.',2),('00000073-0000-4000-8000-000000152013','00000043-0000-4000-8000-000000015201','Imponha derivabilidade','Em $x=1$, as derivadas laterais exigem $a=2$.',3),('00000073-0000-4000-8000-000000152014','00000043-0000-4000-8000-000000015201','Resolva o sistema','Substituir em $a+b=2$ fornece $b=0$.',4),('00000073-0000-4000-8000-000000152015','00000043-0000-4000-8000-000000015201','Verifique','Os dois valores são 2 e as duas inclinações são 2.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015202','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Na curva $x^2+xy+y^2=7$, determine $y^{\prime\prime}$ no ponto $(1,2)$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152021','00000043-0000-4000-8000-000000015202','A','$-\frac{14}{25}$',1),('00000053-0000-4000-8000-000000152022','00000043-0000-4000-8000-000000015202','B','$-\frac45$',2),('00000053-0000-4000-8000-000000152023','00000043-0000-4000-8000-000000015202','C','$\frac{14}{25}$',3),('00000053-0000-4000-8000-000000152024','00000043-0000-4000-8000-000000015202','D','$-\frac{4}{25}$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
