insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015202','30000000-0000-4000-8000-000000000026',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152021','00000043-0000-4000-8000-000000015202','Primeiro encontre $y^{\prime}$ como função de $x$ e $y$.',1),('00000063-0000-4000-8000-000000152022','00000043-0000-4000-8000-000000015202','Na segunda derivação, lembre que $y^{\prime}$ também depende de $x$.',2),('00000063-0000-4000-8000-000000152023','00000043-0000-4000-8000-000000015202','Só substitua $(1,2)$ ao final.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015202','$-\frac{14}{25}$','aplicar derivação implícita de segunda ordem. $2x+xy^{\prime}+y+2yy^{\prime}=0$. $y^{\prime}=-(2x+y)/(x+2y)$; no ponto, ela vale $-4/5$. A derivada da primeira igualdade é $2+xy^{\prime\prime}+2y^{\prime}+2(y^{\prime})^2+2yy^{\prime\prime}=0$. Isso produz $2+5y^{\prime\prime}-8/5+32/25=0$. Logo $y^{\prime\prime}=-14/25$. O resultado é $-\frac{14}{25}$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152021','00000043-0000-4000-8000-000000015202','Diferencie uma vez','$2x+xy^{\prime}+y+2yy^{\prime}=0$.',1),('00000073-0000-4000-8000-000000152022','00000043-0000-4000-8000-000000015202','Isole a primeira derivada','$y^{\prime}=-(2x+y)/(x+2y)$; no ponto, ela vale $-4/5$.',2),('00000073-0000-4000-8000-000000152023','00000043-0000-4000-8000-000000015202','Diferencie novamente','A derivada da primeira igualdade é $2+xy^{\prime\prime}+2y^{\prime}+2(y^{\prime})^2+2yy^{\prime\prime}=0$.',3),('00000073-0000-4000-8000-000000152024','00000043-0000-4000-8000-000000015202','Substitua o ponto','Isso produz $2+5y^{\prime\prime}-8/5+32/25=0$.',4),('00000073-0000-4000-8000-000000152025','00000043-0000-4000-8000-000000015202','Resolva','Logo $y^{\prime\prime}=-14/25$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015203','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Para $x>0$, encontre a derivada de $y=(x^2+1)^x$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152031','00000043-0000-4000-8000-000000015203','A','$y^{\prime}=(x^2+1)^x\left[\ln(x^2+1)+\frac{2x^2}{x^2+1}\right]$',1),('00000053-0000-4000-8000-000000152032','00000043-0000-4000-8000-000000015203','B','$x(x^2+1)^{x-1}$',2),('00000053-0000-4000-8000-000000152033','00000043-0000-4000-8000-000000015203','C','$(x^2+1)^x\ln(x^2+1)$',3),('00000053-0000-4000-8000-000000152034','00000043-0000-4000-8000-000000015203','D','$2x(x^2+1)^x$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015203','00000053-0000-4000-8000-000000152031') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015203','30000000-0000-4000-8000-000000000026',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152031','00000043-0000-4000-8000-000000015203','A variável aparece tanto na base quanto no expoente.',1),('00000063-0000-4000-8000-000000152032','00000043-0000-4000-8000-000000015203','Tomar logaritmo transforma a potência em produto.',2),('00000063-0000-4000-8000-000000152033','00000043-0000-4000-8000-000000015203','Use a regra do produto antes de multiplicar de volta por $y$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015203','$y^{\prime}=(x^2+1)^x\left[\ln(x^2+1)+\frac{2x^2}{x^2+1}\right]$','usar diferenciação logarítmica. $\ln y=x\ln(x^2+1)$. $y^{\prime}/y=\ln(x^2+1)+x\cdot2x/(x^2+1)$. O segundo termo é $2x^2/(x^2+1)$. Multiplique ambos os lados por $(x^2+1)^x$. $x>0$ torna o uso do logaritmo e a potência real compatíveis. O resultado é $y^{\prime}=(x^2+1)^x\left[\ln(x^2+1)+\frac{2x^2}{x^2+1}\right]$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152031','00000043-0000-4000-8000-000000015203','Aplique logaritmo','$\ln y=x\ln(x^2+1)$.',1),('00000073-0000-4000-8000-000000152032','00000043-0000-4000-8000-000000015203','Diferencie implicitamente','$y^{\prime}/y=\ln(x^2+1)+x\cdot2x/(x^2+1)$.',2),('00000073-0000-4000-8000-000000152033','00000043-0000-4000-8000-000000015203','Simplifique','O segundo termo é $2x^2/(x^2+1)$.',3),('00000073-0000-4000-8000-000000152034','00000043-0000-4000-8000-000000015203','Restaure y','Multiplique ambos os lados por $(x^2+1)^x$.',4),('00000073-0000-4000-8000-000000152035','00000043-0000-4000-8000-000000015203','Cheque o domínio','$x>0$ torna o uso do logaritmo e a potência real compatíveis.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015204','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Encontre os extremos absolutos de $f(x)=x+4/x$ em $[1,8]$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152041','00000043-0000-4000-8000-000000015204','A','Mínimo absoluto $4$ em $x=2$; máximo absoluto $17/2$ em $x=8$.',1),('00000053-0000-4000-8000-000000152042','00000043-0000-4000-8000-000000015204','B','Mínimo $4$ em $x=1$; máximo $8$ em $x=8$',2),('00000053-0000-4000-8000-000000152043','00000043-0000-4000-8000-000000015204','C','Mínimo $2$ em $x=2$; máximo $9$ em $x=1$',3),('00000053-0000-4000-8000-000000152044','00000043-0000-4000-8000-000000015204','D','Não há extremos absolutos.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015204','00000053-0000-4000-8000-000000152041') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015204','30000000-0000-4000-8000-000000000029',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152041','00000043-0000-4000-8000-000000015204','Como o intervalo é fechado e a função é contínua nele, compare todos os candidatos.',1),('00000063-0000-4000-8000-000000152042','00000043-0000-4000-8000-000000015204','O ponto crítico vem de anular a derivada, não a função.',2),('00000063-0000-4000-8000-000000152043','00000043-0000-4000-8000-000000015204','Inclua obrigatoriamente $x=1$ e $x=8$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015204','Mínimo absoluto $4$ em $x=2$; máximo absoluto $17/2$ em $x=8$.','comparar extremos absolutos com restrição de domínio. A função é contínua em $[1,8]$, pois zero não pertence ao intervalo. $f^{\prime}(x)=1-4/x^2$. $f^{\prime}=0$ dá $x=2$ no intervalo; $x=-2$ não pertence a ele. $f(1)=5$, $f(2)=4$ e $f(8)=17/2$. O menor é 4 e o maior é $17/2$, nas abscissas indicadas. O resultado é Mínimo absoluto $4$ em $x=2$; máximo absoluto $17/2$ em $x=8$..') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152041','00000043-0000-4000-8000-000000015204','Garanta a existência','A função é contínua em $[1,8]$, pois zero não pertence ao intervalo.',1),('00000073-0000-4000-8000-000000152042','00000043-0000-4000-8000-000000015204','Derive','$f^{\prime}(x)=1-4/x^2$.',2),('00000073-0000-4000-8000-000000152043','00000043-0000-4000-8000-000000015204','Encontre críticos','$f^{\prime}=0$ dá $x=2$ no intervalo; $x=-2$ não pertence a ele.',3),('00000073-0000-4000-8000-000000152044','00000043-0000-4000-8000-000000015204','Avalie candidatos','$f(1)=5$, $f(2)=4$ e $f(8)=17/2$.',4),('00000073-0000-4000-8000-000000152045','00000043-0000-4000-8000-000000015204','Compare','O menor é 4 e o maior é $17/2$, nas abscissas indicadas.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015205','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Uma função tem $f^{\prime}(x)=x(x-2)^2(x-4)$. Em quais intervalos ela cresce e decresce?') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152051','00000043-0000-4000-8000-000000015205','A','Cresce em $(-\infty,0)\cup(4,\infty)$ e decresce em $(0,4)$.',1),('00000053-0000-4000-8000-000000152052','00000043-0000-4000-8000-000000015205','B','Cresce em $(0,2)\cup(2,4)$',2),('00000053-0000-4000-8000-000000152053','00000043-0000-4000-8000-000000015205','C','Decresce em $(-\infty,0)\cup(4,\infty)$',3),('00000053-0000-4000-8000-000000152054','00000043-0000-4000-8000-000000015205','D','Cresce em todo o domínio.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015205','00000053-0000-4000-8000-000000152051') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015205','30000000-0000-4000-8000-000000000030',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152051','00000043-0000-4000-8000-000000015205','O fator ao quadrado não troca de sinal ao ser atravessado.',1),('00000063-0000-4000-8000-000000152052','00000043-0000-4000-8000-000000015205','Construa uma tabela usando os pontos 0, 2 e 4.',2),('00000063-0000-4000-8000-000000152053','00000043-0000-4000-8000-000000015205','O sinal da derivada determina crescimento, não o sinal da função.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015205','Cresce em $(-\infty,0)\cup(4,\infty)$ e decresce em $(0,4)$.','interpretar multiplicidade em tabela de sinais. Os zeros são 0, 2 e 4. $(x-2)^2$ é não negativo e não altera o sinal fora de seu zero. O sinal de $x(x-4)$ é positivo fora de $[0,4]$ e negativo no interior. Em 2 a derivada zera, mas seu sinal não muda. Logo os intervalos de crescimento e decrescimento são os indicados. O resultado é Cresce em $(-\infty,0)\cup(4,\infty)$ e decresce em $(0,4)$..') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152051','00000043-0000-4000-8000-000000015205','Liste os críticos','Os zeros são 0, 2 e 4.',1),('00000073-0000-4000-8000-000000152052','00000043-0000-4000-8000-000000015205','Analise o quadrado','$(x-2)^2$ é não negativo e não altera o sinal fora de seu zero.',2),('00000073-0000-4000-8000-000000152053','00000043-0000-4000-8000-000000015205','Teste intervalos','O sinal de $x(x-4)$ é positivo fora de $[0,4]$ e negativo no interior.',3),('00000073-0000-4000-8000-000000152054','00000043-0000-4000-8000-000000015205','Trate x=2','Em 2 a derivada zera, mas seu sinal não muda.',4),('00000073-0000-4000-8000-000000152055','00000043-0000-4000-8000-000000015205','Conclua','Logo os intervalos de crescimento e decrescimento são os indicados.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015206','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Uma caixa sem tampa tem base quadrada e volume de $32$ m$^3$. Determine o lado da base que minimiza a área de material.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152061','00000043-0000-4000-8000-000000015206','A','$4$ m',1),('00000053-0000-4000-8000-000000152062','00000043-0000-4000-8000-000000015206','B','$2$ m',2),('00000053-0000-4000-8000-000000152063','00000043-0000-4000-8000-000000015206','C','$\sqrt[3]{32}$ m',3),('00000053-0000-4000-8000-000000152064','00000043-0000-4000-8000-000000015206','D','$8$ m',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015206','00000053-0000-4000-8000-000000152061') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015206','30000000-0000-4000-8000-000000000032',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152061','00000043-0000-4000-8000-000000015206','Use o volume para eliminar a altura antes de derivar.',1),('00000063-0000-4000-8000-000000152062','00000043-0000-4000-8000-000000015206','A área tem uma base e quatro faces laterais.',2),('00000063-0000-4000-8000-000000152063','00000043-0000-4000-8000-000000015206','Confirme que o crítico dá mínimo pelo sinal ou pela segunda derivada.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015206','$4$ m','modelar e otimizar sob restrição. Se o lado é $x$, então $x^2h=32$ e $h=32/x^2$. Sem tampa, $A(x)=x^2+4xh=x^2+128/x$, com $x>0$. $A^{\prime}(x)=2x-128/x^2$. $2x^3=128$, portanto $x=4$. $A^{\prime\prime}(x)=2+256/x^3>0$, então o ponto é mínimo. O resultado é $4$ m.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152061','00000043-0000-4000-8000-000000015206','Modele a altura','Se o lado é $x$, então $x^2h=32$ e $h=32/x^2$.',1),('00000073-0000-4000-8000-000000152062','00000043-0000-4000-8000-000000015206','Escreva a área','Sem tampa, $A(x)=x^2+4xh=x^2+128/x$, com $x>0$.',2),('00000073-0000-4000-8000-000000152063','00000043-0000-4000-8000-000000015206','Derive','$A^{\prime}(x)=2x-128/x^2$.',3),('00000073-0000-4000-8000-000000152064','00000043-0000-4000-8000-000000015206','Encontre o crítico','$2x^3=128$, portanto $x=4$.',4),('00000073-0000-4000-8000-000000152065','00000043-0000-4000-8000-000000015206','Classifique','$A^{\prime\prime}(x)=2+256/x^3>0$, então o ponto é mínimo.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015207','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Aplique uma iteração de Newton a $f(x)=x^3-2x-5$, partindo de $x_0=2$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152071','00000043-0000-4000-8000-000000015207','A','$x_1=21/10$',1),('00000053-0000-4000-8000-000000152072','00000043-0000-4000-8000-000000015207','B','$x_1=19/10$',2),('00000053-0000-4000-8000-000000152073','00000043-0000-4000-8000-000000015207','C','$x_1=5/2$',3),('00000053-0000-4000-8000-000000152074','00000043-0000-4000-8000-000000015207','D','$x_1=2$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
