insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015207','30000000-0000-4000-8000-000000000033',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152071','00000043-0000-4000-8000-000000015207','Newton usa o valor da função e a inclinação no mesmo ponto inicial.',1),('00000063-0000-4000-8000-000000152072','00000043-0000-4000-8000-000000015207','Calcule $f(2)$ e $f^{\prime}(2)$ separadamente.',2),('00000063-0000-4000-8000-000000152073','00000043-0000-4000-8000-000000015207','O próximo valor é a interseção da tangente com o eixo x.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015207','$x_1=21/10$','executar Newton e interpretar a correção. $f^{\prime}(x)=3x^2-2$. $f(2)=-1$ e $f^{\prime}(2)=10$. $x_1=x_0-f(x_0)/f^{\prime}(x_0)$. $x_1=2-(-1)/10=21/10$. A correção é positiva porque a tangente em 2 cruza o eixo à direita. O resultado é $x_1=21/10$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152071','00000043-0000-4000-8000-000000015207','Derive','$f^{\prime}(x)=3x^2-2$.',1),('00000073-0000-4000-8000-000000152072','00000043-0000-4000-8000-000000015207','Avalie no chute','$f(2)=-1$ e $f^{\prime}(2)=10$.',2),('00000073-0000-4000-8000-000000152073','00000043-0000-4000-8000-000000015207','Use Newton','$x_1=x_0-f(x_0)/f^{\prime}(x_0)$.',3),('00000073-0000-4000-8000-000000152074','00000043-0000-4000-8000-000000015207','Substitua','$x_1=2-(-1)/10=21/10$.',4),('00000073-0000-4000-8000-000000152075','00000043-0000-4000-8000-000000015207','Interprete','A correção é positiva porque a tangente em 2 cruza o eixo à direita.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015208','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Calcule $\lim_{x\to-\infty}(\sqrt{x^2-2x}+x)$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
