insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152081','00000043-0000-4000-8000-000000015208','Para $x$ negativo, $\sqrt{x^2}$ é $|x|$, não $x$.',1),('00000063-0000-4000-8000-000000152082','00000043-0000-4000-8000-000000015208','Racionalize a soma para evitar subtração de termos grandes.',2),('00000063-0000-4000-8000-000000152083','00000043-0000-4000-8000-000000015208','Ao dividir por $-x$, preserve o sinal.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015208','$1$','racionalizar limite no infinito com valor absoluto. Multiplique por $\sqrt{x^2-2x}-x$. A expressão vira $-2x/(\sqrt{x^2-2x}-x)$. Para $x\to-\infty$, divida numerador e denominador por $-x$. O denominador tende a $\sqrt{1}+1=2$ e o numerador tende a 2. A razão tende a 1. O resultado é $1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152081','00000043-0000-4000-8000-000000015208','Racionalize','Multiplique por $\sqrt{x^2-2x}-x$.',1),('00000073-0000-4000-8000-000000152082','00000043-0000-4000-8000-000000015208','Simplifique','A expressão vira $-2x/(\sqrt{x^2-2x}-x)$.',2),('00000073-0000-4000-8000-000000152083','00000043-0000-4000-8000-000000015208','Use o sinal de x','Para $x\to-\infty$, divida numerador e denominador por $-x$.',3),('00000073-0000-4000-8000-000000152084','00000043-0000-4000-8000-000000015208','Calcule o limite','O denominador tende a $\sqrt{1}+1=2$ e o numerador tende a 2.',4),('00000073-0000-4000-8000-000000152085','00000043-0000-4000-8000-000000015208','Conclua','A razão tende a 1.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015209','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Verifique o Teorema do Valor Médio para $f(x)=\ln x$ em $[1,e^2]$ e encontre o ponto garantido.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152091','00000043-0000-4000-8000-000000015209','A','$c=(e^2-1)/2$',1),('00000053-0000-4000-8000-000000152092','00000043-0000-4000-8000-000000015209','B','$c=e$',2),('00000053-0000-4000-8000-000000152093','00000043-0000-4000-8000-000000015209','C','$c=2$',3),('00000053-0000-4000-8000-000000152094','00000043-0000-4000-8000-000000015209','D','$c=e^2$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015209','00000053-0000-4000-8000-000000152091') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015209','30000000-0000-4000-8000-000000000029',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152091','00000043-0000-4000-8000-000000015209','Cheque continuidade e derivabilidade antes de igualar inclinações.',1),('00000063-0000-4000-8000-000000152092','00000043-0000-4000-8000-000000015209','A inclinação secante usa os valores nas extremidades.',2),('00000063-0000-4000-8000-000000152093','00000043-0000-4000-8000-000000015209','Resolva $1/c$ igual à inclinação obtida.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015209','$c=(e^2-1)/2$','aplicar TVM com verificação de hipóteses. $\ln x$ é contínua em $[1,e^2]$ e derivável em $(1,e^2)$. $(\ln e^2-\ln1)/(e^2-1)=2/(e^2-1)$. $f^{\prime}(x)=1/x$. $1/c=2/(e^2-1)$. $c=(e^2-1)/2$, que está dentro do intervalo. O resultado é $c=(e^2-1)/2$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152091','00000043-0000-4000-8000-000000015209','Verifique hipóteses','$\ln x$ é contínua em $[1,e^2]$ e derivável em $(1,e^2)$.',1),('00000073-0000-4000-8000-000000152092','00000043-0000-4000-8000-000000015209','Calcule a secante','$(\ln e^2-\ln1)/(e^2-1)=2/(e^2-1)$.',2),('00000073-0000-4000-8000-000000152093','00000043-0000-4000-8000-000000015209','Derive','$f^{\prime}(x)=1/x$.',3),('00000073-0000-4000-8000-000000152094','00000043-0000-4000-8000-000000015209','Iguale inclinações','$1/c=2/(e^2-1)$.',4),('00000073-0000-4000-8000-000000152095','00000043-0000-4000-8000-000000015209','Conclua','$c=(e^2-1)/2$, que está dentro do intervalo.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015210','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Um balão esférico recebe ar a $12\pi$ cm$^3$/s. Quando $r=3$ cm, com que taxa cresce sua área?') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152101','00000043-0000-4000-8000-000000015210','A','$8\pi$ cm$^2$/s',1),('00000053-0000-4000-8000-000000152102','00000043-0000-4000-8000-000000015210','B','$12\pi$ cm$^2$/s',2),('00000053-0000-4000-8000-000000152103','00000043-0000-4000-8000-000000015210','C','$24\pi$ cm$^2$/s',3),('00000053-0000-4000-8000-000000152104','00000043-0000-4000-8000-000000015210','D','$4\pi$ cm$^2$/s',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015210','00000053-0000-4000-8000-000000152101') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015210','30000000-0000-4000-8000-000000000027',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152101','00000043-0000-4000-8000-000000015210','Volume fornece $dr/dt$; área usa esse resultado depois.',1),('00000063-0000-4000-8000-000000152102','00000043-0000-4000-8000-000000015210','Diferencie as fórmulas em relação ao tempo.',2),('00000063-0000-4000-8000-000000152103','00000043-0000-4000-8000-000000015210','Não substitua o raio antes de obter as relações de taxa.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015210','$8\pi$ cm$^2$/s','encadear duas taxas relacionadas. $V=4\pi r^3/3$, então $dV/dt=4\pi r^2dr/dt$. Em $r=3$, $12\pi=36\pi,dr/dt$, logo $dr/dt=1/3$. $A=4\pi r^2$, então $dA/dt=8\pi r,dr/dt$. Em $r=3$, $dA/dt=8\pi\cdot3\cdot(1/3)$. A área cresce a $8\pi$ cm$^2$/s. O resultado é $8\pi$ cm$^2$/s.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152101','00000043-0000-4000-8000-000000015210','Relacione volume e raio','$V=4\pi r^3/3$, então $dV/dt=4\pi r^2dr/dt$.',1),('00000073-0000-4000-8000-000000152102','00000043-0000-4000-8000-000000015210','Calcule a taxa do raio','Em $r=3$, $12\pi=36\pi,dr/dt$, logo $dr/dt=1/3$.',2),('00000073-0000-4000-8000-000000152103','00000043-0000-4000-8000-000000015210','Relacione área e raio','$A=4\pi r^2$, então $dA/dt=8\pi r,dr/dt$.',3),('00000073-0000-4000-8000-000000152104','00000043-0000-4000-8000-000000015210','Substitua','Em $r=3$, $dA/dt=8\pi\cdot3\cdot(1/3)$.',4),('00000073-0000-4000-8000-000000152105','00000043-0000-4000-8000-000000015210','Conclua','A área cresce a $8\pi$ cm$^2$/s.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015211','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Calcule $\lim_{x\to0}\frac{\ln(1+x)-x}{x^2}$.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152111','00000043-0000-4000-8000-000000015211','A','$-\frac12$',1),('00000053-0000-4000-8000-000000152112','00000043-0000-4000-8000-000000015211','B','$0$',2),('00000053-0000-4000-8000-000000152113','00000043-0000-4000-8000-000000015211','C','$\frac12$',3),('00000053-0000-4000-8000-000000152114','00000043-0000-4000-8000-000000015211','D','O limite não existe.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('00000043-0000-4000-8000-000000015211','00000053-0000-4000-8000-000000152111') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('00000043-0000-4000-8000-000000015211','30000000-0000-4000-8000-000000000018',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152111','00000043-0000-4000-8000-000000015211','A substituição produz $0/0$.',1),('00000063-0000-4000-8000-000000152112','00000043-0000-4000-8000-000000015211','Após derivar, ainda haverá uma indeterminação.',2),('00000063-0000-4000-8000-000000152113','00000043-0000-4000-8000-000000015211','A derivada de $1/(1+x)-1$ deve ser feita com atenção.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015211','$-\frac12$','resolver limite logarítmico por L’Hôpital. Em zero, o numerador e o denominador valem zero. A razão torna-se $[1/(1+x)-1]/(2x)$, ainda $0/0$. O numerador vira $-1/(1+x)^2$ e o denominador vira 2. Em $x=0$, a razão é $-1/2$. As duas aplicações foram válidas porque cada etapa tinha forma $0/0$. O resultado é $-\frac12$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152111','00000043-0000-4000-8000-000000015211','Teste a forma','Em zero, o numerador e o denominador valem zero.',1),('00000073-0000-4000-8000-000000152112','00000043-0000-4000-8000-000000015211','Aplique L’Hôpital','A razão torna-se $[1/(1+x)-1]/(2x)$, ainda $0/0$.',2),('00000073-0000-4000-8000-000000152113','00000043-0000-4000-8000-000000015211','Derive novamente','O numerador vira $-1/(1+x)^2$ e o denominador vira 2.',3),('00000073-0000-4000-8000-000000152114','00000043-0000-4000-8000-000000015211','Avalie','Em $x=0$, a razão é $-1/2$.',4),('00000073-0000-4000-8000-000000152115','00000043-0000-4000-8000-000000015211','Verifique','As duas aplicações foram válidas porque cada etapa tinha forma $0/0$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015212','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Uma empresa tem lucro $L(x)=-x^3+12x^2-36x+5$ para $x\ge0$. Qual produção localmente maximiza o lucro e qual é o lucro correspondente?') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152121','00000043-0000-4000-8000-000000015212','A','$x=6$ e $L(6)=5$',1),('00000053-0000-4000-8000-000000152122','00000043-0000-4000-8000-000000015212','B','$x=2$ e $L(2)=-27$',2),('00000053-0000-4000-8000-000000152123','00000043-0000-4000-8000-000000015212','C','$x=2$ e $L(2)=5$',3),('00000053-0000-4000-8000-000000152124','00000043-0000-4000-8000-000000015212','D','$x=6$ e $L(6)=-27$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
