insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152121','00000043-0000-4000-8000-000000015212','O ponto crítico precisa ser classificado, não apenas encontrado.',1),('00000063-0000-4000-8000-000000152122','00000043-0000-4000-8000-000000015212','Fatore a primeira derivada antes de testar o sinal.',2),('00000063-0000-4000-8000-000000152123','00000043-0000-4000-8000-000000015212','Calcule o lucro somente depois de decidir qual crítico é máximo.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015212','$x=6$ e $L(6)=5$','classificar extremos de modelo cúbico. $L^{\prime}(x)=-3x^2+24x-36=-3(x-2)(x-6)$. Os candidatos internos são $x=2$ e $x=6$. A derivada muda de negativa para positiva em 2 e de positiva para negativa em 6. Assim, o máximo local ocorre em $x=6$, não em 2. Temos $L(6)=5$; portanto a alternativa correta é $x=6$ e $L(6)=5$. O resultado é $x=6$ e $L(6)=5$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152121','00000043-0000-4000-8000-000000015212','Derive','$L^{\prime}(x)=-3x^2+24x-36=-3(x-2)(x-6)$.',1),('00000073-0000-4000-8000-000000152122','00000043-0000-4000-8000-000000015212','Localize críticos','Os candidatos internos são $x=2$ e $x=6$.',2),('00000073-0000-4000-8000-000000152123','00000043-0000-4000-8000-000000015212','Classifique','A derivada muda de negativa para positiva em 2 e de positiva para negativa em 6.',3),('00000073-0000-4000-8000-000000152124','00000043-0000-4000-8000-000000015212','Escolha o máximo','Assim, o máximo local ocorre em $x=6$, não em 2.',4),('00000073-0000-4000-8000-000000152125','00000043-0000-4000-8000-000000015212','Avalie','Temos $L(6)=5$; portanto a alternativa correta é $x=6$ e $L(6)=5$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015213','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001502','multiple_choice','hard','published','Para $f(x)=x/(x^2+1)$, determine os pontos de inflexão.') on conflict (id) do update set statement_markdown=excluded.statement_markdown,difficulty=excluded.difficulty,publication_status=excluded.publication_status;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000152131','00000043-0000-4000-8000-000000015213','A','$(-\sqrt3,-\sqrt3/4)$, $(0,0)$ e $(\sqrt3,\sqrt3/4)$',1),('00000053-0000-4000-8000-000000152132','00000043-0000-4000-8000-000000015213','B','$(-1,-1/2)$ e $(1,1/2)$',2),('00000053-0000-4000-8000-000000152133','00000043-0000-4000-8000-000000015213','C','$(-\sqrt3,-\sqrt3/4)$ e $(\sqrt3,\sqrt3/4)$',3),('00000053-0000-4000-8000-000000152134','00000043-0000-4000-8000-000000015213','D','Não há pontos de inflexão.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
