insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152131','00000043-0000-4000-8000-000000015213','Ponto de inflexão exige mudança de concavidade, não só $f^{\prime\prime}=0$.',1),('00000063-0000-4000-8000-000000152132','00000043-0000-4000-8000-000000015213','Use a regra do quociente para obter a primeira derivada.',2),('00000063-0000-4000-8000-000000152133','00000043-0000-4000-8000-000000015213','O denominador da segunda derivada nunca muda de sinal.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015213','$(-\sqrt3,-\sqrt3/4)$, $(0,0)$ e $(\sqrt3,\sqrt3/4)$','analisar concavidade por segunda derivada. $f^{\prime}(x)=(1-x^2)/(x^2+1)^2$. $f^{\prime\prime}(x)=2x(x^2-3)/(x^2+1)^3$. Os zeros são $-\sqrt3$, 0 e $\sqrt3$. O sinal muda ao atravessar cada um dos três zeros. Os três valores correspondentes de $f$ dão os pontos indicados. O resultado é $(-\sqrt3,-\sqrt3/4)$, $(0,0)$ e $(\sqrt3,\sqrt3/4)$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152131','00000043-0000-4000-8000-000000015213','Derive uma vez','$f^{\prime}(x)=(1-x^2)/(x^2+1)^2$.',1),('00000073-0000-4000-8000-000000152132','00000043-0000-4000-8000-000000015213','Derive novamente','$f^{\prime\prime}(x)=2x(x^2-3)/(x^2+1)^3$.',2),('00000073-0000-4000-8000-000000152133','00000043-0000-4000-8000-000000015213','Ache candidatos','Os zeros são $-\sqrt3$, 0 e $\sqrt3$.',3),('00000073-0000-4000-8000-000000152134','00000043-0000-4000-8000-000000015213','Teste concavidade','O sinal muda ao atravessar cada um dos três zeros.',4),('00000073-0000-4000-8000-000000152135','00000043-0000-4000-8000-000000015213','Conclua','Os três valores correspondentes de $f$ dão os pontos indicados.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
