insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000152141','00000043-0000-4000-8000-000000015214','Assíntota oblíqua vem da divisão polinomial quando o grau do numerador excede o do denominador por um.',1),('00000063-0000-4000-8000-000000152142','00000043-0000-4000-8000-000000015214','Faça a divisão antes de descartar o termo restante.',2),('00000063-0000-4000-8000-000000152143','00000043-0000-4000-8000-000000015214','O resto dividido por $x-1$ deve tender a zero no infinito.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015214','$y=2x-1$','encontrar assíntota oblíqua por divisão. $2x^2/x=2x$. $(2x^2-3x+5)-(2x^2-2x)=-x+5$. $-x/x=-1$, restando 4. $f(x)=2x-1+4/(x-1)$. O último termo tende a zero, então a reta é $y=2x-1$. O resultado é $y=2x-1$.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000152141','00000043-0000-4000-8000-000000015214','Divida os termos líderes','$2x^2/x=2x$.',1),('00000073-0000-4000-8000-000000152142','00000043-0000-4000-8000-000000015214','Subtraia','$(2x^2-3x+5)-(2x^2-2x)=-x+5$.',2),('00000073-0000-4000-8000-000000152143','00000043-0000-4000-8000-000000015214','Continue a divisão','$-x/x=-1$, restando 4.',3),('00000073-0000-4000-8000-000000152144','00000043-0000-4000-8000-000000015214','Reescreva','$f(x)=2x-1+4/(x-1)$.',4),('00000073-0000-4000-8000-000000152145','00000043-0000-4000-8000-000000015214','Tome o limite','O último termo tende a zero, então a reta é $y=2x-1$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
